fn solve(input: Vec<(i8, i8)>) -> Vec<i8> {
    input
        .into_iter()
        .map(|(a, b)| {
            let d = b - a;
            if d == 0 {
                // No change needed.
                0
            } else if d > 0 {
                // We need a net increase of d > 0.
                // One odd increment suffices if d is odd;
                // otherwise we can do two odd increments to make an even total.
                if d & 1 != 0 {
                    1
                } else {
                    2
                }
            } else {
                // d < 0: we need a net decrease of -d.
                // One even decrement suffices if -d is even;
                // otherwise we do one odd increment and one even decrement.
                if d & 1 == 0 {
                    1
                } else {
                    2
                }
            }
        })
        .collect()
}

